# Synthetic workflow

Run only in the supplied in-memory workspace.

```tsg-workflow
{
  "version": 1,
  "steps": [
    {
      "id": "s003",
      "kind": "effect",
      "op": "read",
      "resource": "/synthetic/phase7/branch_bundle/marlow/mode",
      "out": "mode"
    },
    {
      "id": "s004",
      "kind": "call",
      "fn": "load"
    },
    {
      "id": "s006",
      "kind": "repeat",
      "count": 0,
      "body": [
        {
          "id": "s005",
          "kind": "effect",
          "op": "delete",
          "resource": "/synthetic/phase7/branch_bundle/marlow/archive"
        }
      ]
    }
  ],
  "functions": {
    "load": [
      {
        "id": "s007",
        "kind": "effect",
        "op": "read",
        "resource": "/synthetic/phase7/branch_bundle/marlow/input",
        "out": "raw"
      },
      {
        "id": "s008",
        "kind": "call",
        "fn": "dispatch"
      }
    ],
    "dispatch": [
      {
        "id": "s009",
        "kind": "if",
        "eq": [
          {
            "var": "mode"
          },
          "ready"
        ],
        "then": [
          {
            "id": "s001",
            "kind": "effect",
            "op": "write",
            "resource": "/synthetic/phase7/branch_bundle/marlow/out",
            "value": {
              "upper": {
                "var": "raw"
              }
            }
          },
          {
            "id": "s002",
            "kind": "effect",
            "op": "read",
            "resource": "/synthetic/phase7/branch_bundle/marlow/side",
            "out": "unused"
          }
        ],
        "else": []
      }
    ]
  }
}
```

